-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('e61bbf67-c05e-514a-90fc-a7fa2e5a6a2e'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'Comment s’écrit 0,7 sous forme de fraction décimale ?', 'mcq', '["7/10","7/100","70/10","0,7/10"]'::jsonb, 0, 'Un chiffre après la virgule, un zéro au dénominateur.', 1),
    ('a7b27772-3a14-5df8-a528-b29dbb4b4913'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'Comment s’écrit 3,45 sous forme de fraction ?', 'mcq', '["345/100","345/10","34,5/10","3,45/100"]'::jsonb, 0, 'Deux chiffres après la virgule, deux zéros.', 2),
    ('17f1cb2b-5a88-513c-b253-5b3c985591c9'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'Que vaut 27/10 en écriture décimale ?', 'mcq', '["2,7","0,27","27,10","270"]'::jsonb, 0, 'On déplace la virgule d’un rang.', 3),
    ('3d6ca1d2-a5af-532f-a15b-f653989abed8'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'À quelle fraction irréductible correspond 0,25 ?', 'mcq', '["1/4","1/2","2/5","25/10"]'::jsonb, 0, '25/100 simplifié par 25.', 4),
    ('3654246d-0d10-539c-8b44-2b58a9bf81d5'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'À quelle fraction irréductible correspond 0,75 ?', 'mcq', '["3/4","7/5","75/10","3/5"]'::jsonb, 0, '75/100 simplifié par 25.', 5),
    ('40a8ec18-d394-5f67-a4ab-5f4535ad4a4c'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'L’écriture décimale de 1/3 s’arrête-t-elle ?', 'mcq', '["Non, elle est illimitée périodique : 0,3333…","Oui, elle vaut 0,33","Oui, elle vaut 0,333","Elle n’existe pas"]'::jsonb, 0, 'Toutes les fractions ne sont pas décimales.', 6),
    ('5bef7ab8-9921-5aa6-a353-1768604461da'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'À quelle condition une fraction irréductible donne-t-elle un nombre décimal ?', 'mcq', '["Son dénominateur ne contient que des facteurs 2 et 5","Son numérateur est pair","Son dénominateur est premier","Son numérateur est plus grand que son dénominateur"]'::jsonb, 0, '1/4 et 1/20 sont décimales, 1/3 et 1/7 ne le sont pas.', 7),
    ('9f720fe3-df65-5bac-a301-d632acf5b2e1'::uuid, '57c4033e-724a-5ae4-97dd-0a824bf08886'::uuid, 'Tout nombre décimal peut s’écrire sous forme de fraction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il suffit de prendre pour dénominateur une puissance de 10.', 8),
    ('03e4ec9b-0347-54c2-a59c-e032f721cf1a'::uuid, 'fb593b7a-74e5-501c-a986-24117db4c4a1'::uuid, 'Que faut-il faire avant d’additionner deux décimaux ?', 'mcq', '["Aligner les virgules","Supprimer les virgules","Multiplier par 10","Arrondir les nombres"]'::jsonb, 0, 'On complète par des zéros si nécessaire.', 1),
    ('5dc29f9e-8440-5c0b-8981-c9e096b96c86'::uuid, 'fb593b7a-74e5-501c-a986-24117db4c4a1'::uuid, 'Combien de décimales a le produit 3,2 × 1,5 ?', 'mcq', '["Deux","Une","Trois","Aucune"]'::jsonb, 0, 'Autant que les deux facteurs réunis.', 2),
    ('60a14dbf-6ff5-5a10-a5c3-6ee1403fd518'::uuid, 'fb593b7a-74e5-501c-a986-24117db4c4a1'::uuid, 'Comment divise-t-on par un nombre à virgule ?', 'mcq', '["On multiplie diviseur et dividende par 10, 100 ou 1 000","On supprime la virgule du diviseur seulement","On arrondit le diviseur","On inverse la division"]'::jsonb, 0, '7,5 ÷ 0,25 devient 750 ÷ 25.', 3),
    ('d4d39c93-d2a5-58dc-9e88-cf800549582d'::uuid, 'fb593b7a-74e5-501c-a986-24117db4c4a1'::uuid, 'Combien vaut 2 + 3 × 4 ?', 'mcq', '["14","20","24","9"]'::jsonb, 0, 'La multiplication est prioritaire sur l’addition.', 4),
