    ('b9668dbd-a755-5432-b2e6-98498ce878c2'::uuid, '093bbeb9-abe5-5aa4-b39f-dcc829a0f025'::uuid, 'Quelle est la décomposition en facteurs premiers de 60 ?', 'mcq', '["2² × 3 × 5","2 × 3 × 10","4 × 15","2³ × 3 × 5"]'::jsonb, 0, 'On divise successivement par le plus petit facteur premier.', 6),
