    ('c083b78f-7f01-5f66-ac2b-4de3efd66966'::uuid, 'dda227a3-d46f-5e7c-96e7-29c7e40ac20a'::uuid, 'Qu’est-ce que l’effectif d’une valeur ?', 'mcq', '["Le nombre d’individus qui portent cette valeur","La somme de toutes les valeurs","La valeur la plus fréquente","L’écart entre deux valeurs"]'::jsonb, 0, 'L’effectif total est la somme de tous les effectifs.', 1),
