    ('b88aa3d3-479c-59cc-835f-ada730d47797'::uuid, 'c9892236-3731-55e8-8c38-268786b30464'::uuid, 'Un ratio 2 : 3 signifie que le premier reçoit les deux tiers du total.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il reçoit 2/5 : c’est la confusion la plus fréquente du chapitre.', 8),
    ('c93ac25a-af44-5a12-a5e0-92f7a9a4679e'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Quelle est la différence entre périmètre et aire ?', 'mcq', '["Le périmètre est la longueur du contour, l’aire la mesure de la surface","Le périmètre concerne les cercles, l’aire les polygones","Ce sont deux mots pour la même grandeur","L’aire est toujours plus grande"]'::jsonb, 0, 'Ils se mesurent dans des unités différentes.', 1),
    ('4831a363-3584-5b0c-a523-7c4532c818f5'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Quelle est la formule de l’aire d’un triangle ?', 'mcq', '["(base × hauteur) ÷ 2","base × hauteur","somme des trois côtés","(base + hauteur) ÷ 2"]'::jsonb, 0, 'La hauteur doit être relative à la base choisie.', 2),
    ('22c7f38f-5551-5747-bee3-533998ede455'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Quelle est la formule de l’aire d’un disque ?', 'mcq', '["π × R²","2 × π × R","π × D","π × R³"]'::jsonb, 0, '2 × π × R est le périmètre du cercle.', 3),
    ('ac270e50-2ba3-5b43-adb9-50510a0832b5'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Quelle est la formule de l’aire d’un losange ?', 'mcq', '["(D × d) ÷ 2","côté²","base × hauteur","(D + d) ÷ 2"]'::jsonb, 0, 'D et d sont les deux diagonales.', 4),
    ('973d5910-f025-59e0-b706-423e9706b00b'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Que représente le nombre π ?', 'mcq', '["Le rapport entre le périmètre d’un cercle et son diamètre","L’aire d’un cercle de rayon 1","La longueur d’un rayon","Le double du rayon"]'::jsonb, 0, 'Il vaut environ 3,14 pour tous les cercles.', 5),
    ('c9d28574-6242-54ac-a0c4-9e3d26751a0e'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Combien de cm² vaut 1 m² ?', 'mcq', '["10 000 cm²","100 cm²","1 000 cm²","1 000 000 cm²"]'::jsonb, 0, 'Les unités d’aire se convertissent de 100 en 100.', 6),
    ('928513ec-b3be-545e-ad85-19bffdf9ac8f'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Comment calcule-t-on l’aire d’une figure composée ?', 'mcq', '["En la décomposant en figures simples","En mesurant son périmètre","En comptant ses côtés","En prenant la moyenne des aires connues"]'::jsonb, 0, 'On additionne ou on soustrait les aires simples.', 7),
    ('fb40465f-8aeb-5a6e-9ae9-592c1df7363c'::uuid, 'f7378b3e-d1a8-5aae-8fea-f795f00b9a88'::uuid, 'Deux figures de même périmètre ont forcément la même aire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un rectangle 1 × 9 et un carré 5 × 5 ont le même périmètre et des aires de 9 et 25.', 8),
    ('627aa401-0aca-56d0-8a09-fcc6d80ee004'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Qu’est-ce qu’une arête ?', 'mcq', '["Le segment où deux faces se rencontrent","Le point où plusieurs faces se rejoignent","Une face plane du solide","La hauteur du solide"]'::jsonb, 0, 'Le sommet est un point, l’arête un segment.', 1),
    ('b62f7573-ba83-537d-b264-baa3bd2b1ef5'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Combien d’arêtes a un cube ?', 'mcq', '["12","8","6","4"]'::jsonb, 0, '6 faces, 12 arêtes, 8 sommets.', 2),
    ('a11b8096-50d5-573b-9f09-ec15e7acab34'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Qu’est-ce qu’un solide de révolution ?', 'mcq', '["Un solide obtenu en faisant tourner une figure autour d’un axe","Un solide à faces planes","Un solide sans sommet","Un polyèdre régulier"]'::jsonb, 0, 'Cylindre, cône et sphère en sont.', 3),
    ('a8047725-56ec-50b9-b759-8dca8c77aa2a'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Comment trace-t-on les arêtes cachées en perspective cavalière ?', 'mcq', '["En pointillés","En trait plein","On ne les trace pas","En double trait"]'::jsonb, 0, 'La face avant est, elle, en vraie grandeur.', 4),
    ('c3c0248d-4842-5fbe-b7de-77aa5c87bbef'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Que conserve la perspective cavalière ?', 'mcq', '["Le parallélisme et les milieux","Tous les angles droits","Toutes les longueurs","Les aires"]'::jsonb, 0, 'Une face carrée peut y sembler être un parallélogramme.', 5),
    ('4d7a8d7a-c8fe-5ecf-8f29-ce2e551f3c27'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Qu’est-ce qu’un patron ?', 'mcq', '["La figure plane qui, pliée, reconstitue le solide","Une vue de face du solide","Le dessin en perspective","La base du solide"]'::jsonb, 0, 'Sans recouvrement ni manque.', 6),
    ('da5db286-119a-5c30-84a7-f0b328a042c6'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'De quoi se compose le patron d’un cylindre ?', 'mcq', '["De deux disques et d’un rectangle","De deux disques et d’un secteur circulaire","De trois rectangles","D’un disque et d’un triangle"]'::jsonb, 0, 'Un côté du rectangle vaut le périmètre de la base.', 7),
    ('3d7f07d1-d8b9-5731-a2e1-f5ca4b4b5278'::uuid, '5cbee831-6d44-503c-bb11-b7e5153235b3'::uuid, 'Il n’existe qu’un seul patron possible pour le cube.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en existe onze différents.', 8),
    ('900e86c0-f3a8-596b-b3e4-8f2024e6766c'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Quelles sont les faces latérales d’un prisme droit ?', 'mcq', '["Des rectangles","Des triangles","Des trapèzes","Des disques"]'::jsonb, 0, 'Les bases, elles, sont des polygones.', 1),
    ('2b29eaf0-52ad-571f-b802-ea3f83c69028'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Comment obtient-on un cylindre de révolution ?', 'mcq', '["En faisant tourner un rectangle autour d’un de ses côtés","En faisant tourner un triangle","En empilant des disques de rayons différents","En pliant un secteur circulaire"]'::jsonb, 0, 'Le cône s’obtient, lui, avec un triangle rectangle.', 2),
    ('87a80d2a-4088-5aa9-8c74-e65ca80c763a'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Quelle est la formule du volume d’un prisme droit ?', 'mcq', '["Aire de la base × hauteur","(Aire de la base × hauteur) ÷ 3","Périmètre de la base × hauteur","Aire de la base ÷ hauteur"]'::jsonb, 0, 'Le tiers concerne la pyramide et le cône.', 3),
    ('13c7175c-ac52-53c9-8a05-a9bbafc87867'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Quelle est la formule du volume d’un cylindre ?', 'mcq', '["π × R² × h","2 × π × R × h","(π × R² × h) ÷ 3","4 × π × R²"]'::jsonb, 0, 'Aire du disque de base multipliée par la hauteur.', 4),
    ('9c4917ec-932c-5e1d-9ccd-8e964b51be8d'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Que vaut la longueur du rectangle dans le patron d’un cylindre ?', 'mcq', '["Le périmètre du disque de base, soit 2πR","Le rayon du disque","Le diamètre du disque","La hauteur du cylindre"]'::jsonb, 0, 'La surface latérale déroulée est un rectangle.', 5),
    ('e574cc79-e22f-5914-8b5e-779f7d966dd1'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Comment calcule-t-on l’aire latérale d’un prisme droit ?', 'mcq', '["Périmètre de la base × hauteur","Aire de la base × hauteur","Périmètre de la base ÷ 2","Aire de la base × 2"]'::jsonb, 0, 'L’aire totale y ajoute les deux bases.', 6),
    ('ca1a2cd6-182b-5925-912c-053389b6bceb'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Combien de faces a un prisme droit dont la base a 5 côtés ?', 'mcq', '["7","5","10","12"]'::jsonb, 0, 'n + 2 : cinq faces latérales et deux bases.', 7),
    ('6b6e864c-1125-5a46-99b8-9951e2d41068'::uuid, 'da8e2526-2c4d-520a-9999-a1baa0c793a2'::uuid, 'Le volume d’un cylindre se calcule en divisant par 3.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le tiers ne concerne que la pyramide et le cône.', 8),
    ('3c1e6e52-019d-568b-b1ec-bd820b1cc05f'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Que peut-on dire de deux angles opposés par le sommet ?', 'mcq', '["Ils sont toujours égaux","Ils sont supplémentaires","Ils sont complémentaires","Ils sont adjacents"]'::jsonb, 0, 'Quelle que soit la position des droites.', 1),
    ('e7de7a88-ca1d-54db-bf68-2c65d00b0132'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Où se situent deux angles alternes-internes ?', 'mcq', '["De part et d’autre de la sécante, entre les deux droites","Du même côté de la sécante","À l’extérieur des deux droites","Sur la même droite"]'::jsonb, 0, 'Les alternes-externes sont, eux, à l’extérieur.', 2),
    ('cc0729bb-cb87-5b9f-aed7-6fbf603ccf2c'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Que peut-on conclure si deux droites parallèles sont coupées par une sécante ?', 'mcq', '["Les angles alternes-internes sont égaux","Les angles sont tous droits","Les angles sont supplémentaires","On ne peut rien conclure"]'::jsonb, 0, 'Les correspondants le sont aussi.', 3),
    ('61386205-7a21-5d26-8e16-4d1b20203fe5'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Comment démontre-t-on que deux droites sont parallèles ?', 'mcq', '["En montrant que deux angles alternes-internes sont égaux","En mesurant leur écartement","En vérifiant qu’elles ne se coupent pas sur le dessin","En comparant leurs longueurs"]'::jsonb, 0, 'C’est la réciproque de la propriété.', 4),
    ('0502a356-fee2-5436-9755-d7286c74d376'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Que vaut la somme des angles d’un triangle ?', 'mcq', '["180°","360°","90°","Cela dépend du triangle"]'::jsonb, 0, 'Elle se démontre à l’aide des angles alternes-internes.', 5),
    ('0621d70f-5005-549e-aa38-c55af58a4fc4'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Que peut-on dire des deux angles aigus d’un triangle rectangle ?', 'mcq', '["Ils sont complémentaires","Ils sont supplémentaires","Ils sont égaux","Ils valent 60° chacun"]'::jsonb, 0, 'Leur somme vaut 90°.', 6),
    ('69273896-80f8-583c-9c50-94cefd9042b6'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Combien mesure chaque angle d’un triangle équilatéral ?', 'mcq', '["60°","45°","90°","120°"]'::jsonb, 0, '180° ÷ 3.', 7),
    ('b7baf12d-f31c-5fbf-b2ba-13c3e8a6d5c5'::uuid, '34b9bfdf-7aaf-5199-a562-df3225ed251d'::uuid, 'Deux angles correspondants sont toujours égaux, parallèles ou non.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’égalité exige que les deux droites soient parallèles.', 8),
    ('3b34f5f9-2ce6-5a07-8c52-b6a45b5f2645'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Qu’est-ce qu’un triangle isocèle ?', 'mcq', '["Un triangle qui a deux côtés de même longueur","Un triangle qui a trois côtés égaux","Un triangle qui a un angle droit","Un triangle qui a trois angles aigus"]'::jsonb, 0, 'Ses deux angles à la base sont égaux.', 1),
    ('44d6ad61-912d-5095-af9d-1b4136911b0f'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Combien d’axes de symétrie a un triangle équilatéral ?', 'mcq', '["Trois","Un","Deux","Aucun"]'::jsonb, 0, 'Le triangle isocèle n’en a qu’un.', 2),
    ('89c697de-6c2b-5855-b5ec-c5990694093a'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Que peut-on dire des angles à la base d’un triangle isocèle ?', 'mcq', '["Ils sont égaux","Ils sont complémentaires","Ils valent 60°","Ils sont droits"]'::jsonb, 0, 'C’est la propriété la plus utilisée du chapitre.', 3),
    ('0372841e-8335-57e2-9074-4c94552438ae'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Que dit l’inégalité triangulaire ?', 'mcq', '["La plus grande longueur doit être inférieure à la somme des deux autres","Les trois côtés doivent être différents","La somme des angles vaut 180°","Le plus grand angle est opposé au plus grand côté"]'::jsonb, 0, '3, 4 et 9 ne forment pas un triangle.', 4),
    ('faf14504-188b-5c2b-a3d0-4aed1e277161'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Les longueurs 3, 4 et 5 forment-elles un triangle ?', 'mcq', '["Oui, car 3 + 4 > 5","Non, car 3 + 4 = 7","Non, car les longueurs sont trop proches","On ne peut pas le savoir"]'::jsonb, 0, 'La condition de l’inégalité triangulaire est respectée.', 5),
    ('9e921902-1da3-5d90-b57d-0381a0b7a832'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Que se passe-t-il si la plus grande longueur égale la somme des deux autres ?', 'mcq', '["Les trois points sont alignés","Le triangle est équilatéral","Le triangle est rectangle","Le triangle est isocèle"]'::jsonb, 0, 'Le triangle est alors « aplati ».', 6),
    ('dc868868-0212-5067-9a66-813b718cadae'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Quelles données suffisent à construire un triangle ?', 'mcq', '["Trois côtés, ou deux côtés et l’angle entre eux, ou un côté et deux angles","Trois angles","Un côté et un angle","Deux côtés seulement"]'::jsonb, 0, 'Trois angles ne donnent que la forme, pas la taille.', 7),
    ('a3258d25-dc1b-5c75-a0a1-f6e70d6f7599'::uuid, '84c80ce6-6f99-5bee-b0e0-64e4199a3455'::uuid, 'Un triangle peut être à la fois rectangle et isocèle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses deux angles aigus valent alors 45° chacun.', 8),
    ('50f27799-f269-5b6d-a46d-8cd295e13cc0'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Qu’est-ce que la médiatrice d’un segment ?', 'mcq', '["La droite perpendiculaire à ce segment en son milieu","La droite qui joint un sommet au milieu du côté opposé","La droite qui partage un angle en deux","La droite perpendiculaire au côté opposé"]'::jsonb, 0, 'Tout point de la médiatrice est équidistant des extrémités.', 1),
    ('c812be36-41db-532a-ad2b-b3947093bab1'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Où se coupent les trois médiatrices d’un triangle ?', 'mcq', '["Au centre du cercle circonscrit","À l’orthocentre","Au centre de gravité","Au centre du cercle inscrit"]'::jsonb, 0, 'Ce cercle passe par les trois sommets.', 2),
    ('f2c9ed40-a69e-55ca-98a1-1dd2c40a75cf'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Qu’est-ce qu’une médiane ?', 'mcq', '["La droite qui joint un sommet au milieu du côté opposé","La perpendiculaire au côté opposé","La bissectrice d’un angle","La médiatrice d’un côté"]'::jsonb, 0, 'Les trois se coupent au centre de gravité.', 3),
    ('2b3f0646-1432-5876-8409-d326fffde21f'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Où se situe le centre de gravité sur une médiane ?', 'mcq', '["Aux deux tiers en partant du sommet","Au milieu","Au tiers en partant du sommet","Sur le côté opposé"]'::jsonb, 0, 'C’est la propriété à retenir.', 4),
    ('0f2197ae-b183-5cd5-a2ab-95a03ceda822'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Où se coupent les trois hauteurs d’un triangle ?', 'mcq', '["À l’orthocentre","Au centre de gravité","Au centre du cercle inscrit","Au centre du cercle circonscrit"]'::jsonb, 0, 'Il peut être à l’extérieur du triangle si celui-ci est obtusangle.', 5),
    ('2d25ac29-d177-5396-8d76-20ab38502a45'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Que définit le point de concours des bissectrices ?', 'mcq', '["Le centre du cercle inscrit","Le centre du cercle circonscrit","L’orthocentre","Le centre de gravité"]'::jsonb, 0, 'Ce cercle est tangent aux trois côtés.', 6),
    ('a07ed2b1-472d-5396-bf39-9e1d4d517014'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Que partage une médiane en deux parties égales ?', 'mcq', '["L’aire du triangle","L’angle du sommet","Le périmètre","La hauteur"]'::jsonb, 0, 'Les deux triangles obtenus ont la même aire.', 7),
    ('ae2ae6c1-7305-589c-8fce-b688bc87ad2e'::uuid, '98011504-b99d-5818-9975-c4894b890280'::uuid, 'Dans un triangle isocèle, médiatrice, hauteur, médiane et bissectrice issues du sommet principal sont confondues.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et dans un triangle équilatéral, c’est vrai pour les trois sommets.', 8),
    ('0a403771-1852-573d-a015-88485559487b'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Combien vaut la somme des angles d’un triangle ?', 'mcq', '["180°","360°","90°","Cela dépend du triangle"]'::jsonb, 0, 'C’est vrai pour tout triangle, sans exception.', 1),
    ('d36a630f-0d67-5740-99ce-840c91d07132'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Si deux angles d’un triangle valent 65° et 40°, combien vaut le troisième ?', 'mcq', '["75°","85°","105°","95°"]'::jsonb, 0, '180 − 65 − 40.', 2),
    ('504f344f-ee1d-5120-8234-d01bfa3b9af4'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Que peut-on dire des angles aigus d’un triangle rectangle ?', 'mcq', '["Ils sont complémentaires","Ils sont supplémentaires","Ils sont égaux","Ils valent 60° chacun"]'::jsonb, 0, 'Leur somme vaut 90°.', 3),
    ('30478d01-c0fa-51e9-85f7-18097a579f9a'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Combien vaut chaque angle d’un triangle équilatéral ?', 'mcq', '["60°","45°","90°","30°"]'::jsonb, 0, '180° ÷ 3.', 4),
    ('63159bac-a00f-530c-b99f-da7cd5a6ccae'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Dans un triangle isocèle dont l’angle au sommet vaut 40°, combien vaut chaque angle à la base ?', 'mcq', '["70°","40°","50°","80°"]'::jsonb, 0, '(180 − 40) ÷ 2.', 5),
    ('c695ee1f-53ad-5064-90d2-9c80c8ccca53'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Combien un triangle peut-il avoir d’angles obtus ?', 'mcq', '["Un seul","Deux","Trois","Aucun"]'::jsonb, 0, 'Deux angles obtus dépasseraient déjà 180°.', 6),
    ('3729f9a4-dcf1-5bf9-90c7-c493e39433ac'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'À quoi est égal un angle extérieur d’un triangle ?', 'mcq', '["À la somme des deux angles intérieurs non adjacents","À l’angle intérieur adjacent","À 90°","À la moitié de 180°"]'::jsonb, 0, 'C’est une conséquence directe de la propriété des 180°.', 7),
    ('77341270-151c-5985-8d18-2251db979cae'::uuid, '2bbf1aea-a432-54e8-b022-dd0721cf8fac'::uuid, 'Un dessin bien fait suffit à démontrer une égalité d’angles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une figure sert à comprendre ; ce qui prouve, c’est la propriété citée et le calcul.', 8),
