    ('c12521a5-5e24-5995-b799-8c532efedd46'::uuid, '058cea54-8a04-54db-a567-b62f7fa26cf8'::uuid, 'Que peut-on dire des diagonales d’un rectangle ?', 'mcq', '["Elles se coupent en leur milieu et ont la même longueur","Elles sont perpendiculaires","Elles sont parallèles","Elles sont de longueurs différentes"]'::jsonb, 0, 'Le losange a, lui, des diagonales perpendiculaires.', 2),
